  "type": "module",
  "bin": {
    "opencode-pre-tool": "./dist/cli/pre-tool-use.js",
    "opencode-post-tool": "./dist/cli/post-tool-use.js",
    "opencode-session-start": "./dist/cli/session-start.js",
